/* A bounded IndexedDB vault; photos and the durable queue join private exports. */
(()=>{'use strict';const MAX=20000000,records=new Map();let writes=Promise.resolve();let db,draining=false,replayRequested=false,sequence=Date.now(),error='',last=0;const pending=()=>[...records].filter(([k])=>k.startsWith('job:')).map(([,v])=>v).sort((a,b)=>a.order-b.order);const key=()=> 'snapshot:'+pcUrl;
 const ready=new Promise((resolve,reject)=>{const r=indexedDB.open('goblin-studio-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('records');r.onerror=()=>reject(Error('Le stockage des albums est indisponible.'));r.onsuccess=()=>{db=r.result;const t=db.transaction('records','readonly'),store=t.objectStore('records'),cursor=store.openCursor();cursor.onsuccess=()=>{const c=cursor.result;if(c){records.set(c.key,c.value);if(String(c.key).startsWith('job:'))sequence=Math.max(sequence,Number(c.value.order)||0);c.continue()}};t.oncomplete=()=>{mirror();resolve()};t.onerror=()=>reject(t.error)}});
 function mirror(){window.goblinStudioBackup={version:1,records:[...records]};}
 function write(changes){const result=writes.then(()=>writeNow(changes));writes=result.catch(()=>{});return result}
 async function writeNow(changes){await ready;const next=new Map(records);for(const [k,v] of changes){if(v===undefined)next.delete(k);else next.set(k,v)}if(JSON.stringify([...next]).length>MAX)throw Error('Le stockage local des albums est plein. Synchronise le PC et exporte une sauvegarde avant de continuer.');await new Promise((resolve,reject)=>{const t=db.transaction('records','readwrite'),s=t.objectStore('records');for(const [k,v]of changes){if(v===undefined)s.delete(k);else s.put(v,k)}t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('Écriture des albums interrompue.'))});records.clear();for(const [k,v]of next)records.set(k,v);mirror();}
 window.goblinStudioRestore=async backup=>{await ready;if(!backup||backup.version!==1||!Array.isArray(backup.records)||JSON.stringify(backup).length>MAX)throw Error('Sauvegarde des albums invalide.');if(!backup.records.every(r=>Array.isArray(r)&&r.length===2&&typeof r[0]==='string'&&r[0].length<600))throw Error('Clé de sauvegarde invalide.');const changes=[...[...records.keys()].map(k=>[k,undefined]),...backup.records];await write(changes)};
 function overlay(snapshot){const result=structuredClone(snapshot||{objects:[],boards:[],food:[]});result.objects||=[];for(const job of pending()){if(job.base!==pcUrl)continue;const {action,payload:p}=job;if(action==='save'){const i=result.objects.findIndex(o=>o.id===p.id),next={...p,revision:p.revision+1,_pending:true};if(i>=0)result.objects[i]=next;else result.objects.push(next)}if(action==='shopping-save'){result.shopping||=[];const id=p.shopping_id||'studio-'+job.operation_id,i=result.shopping.findIndex(x=>x.id===id),item={...(i>=0?result.shopping[i]:{}),...p,id,_pending:true};if(i>=0)result.shopping[i]=item;else result.shopping.push(item);result.objects=result.objects.filter(o=>o.data.shopping_id!==id);result.objects.push({id:'shopping-'+id,kind:'purchase',data:{title:p.name,shopping_id:id,category:p.category}})}if(action==='shopping-check'){const item=result.shopping?.find(x=>x.id===p.shopping_id);if(item)item.checked=p.checked}if(action==='tracker-setup'){const row=result.boards?.flatMap(b=>b.rows).find(r=>r.id===p.row_id);if(row)Object.assign(row,{title:p.title,mode:p.mode,target_count:p.target_count,weekday:p.weekday});if(p.appearance){result.objects=result.objects.filter(o=>o.id!==p.appearance.id);result.objects.push({...p.appearance,revision:p.appearance.revision+1})}}if(action==='board-title'){const b=result.boards?.find(b=>b.id===p.id);if(b)b.title=p.title}if(action==='row-archive'){for(const b of result.boards||[])b.rows=b.rows.filter(r=>r.id!==p.row_id)}if(action==='tracker-mark'){const row=result.boards?.flatMap(b=>b.rows).find(r=>r.id===p.row_id);if(row){row.marks||={};if(p.mode==='increment')row.marks[p.day]=String(Math.max(0,Math.min(row.target_count||1000000,Number(row.marks[p.day]||0)+(p.delta||1))));else if(p.value)row.marks[p.day]='1';else delete row.marks[p.day]}}if(action==='task-step'){const details=result.task_details?.find(t=>t.task_id===p.task_id);if(details?.data.checklist?.[p.index]?.text===p.text)details.data.checklist[p.index].done=p.done}if(action==='tracker-step'){for(const row of result.boards?.flatMap(b=>b.rows)||[]){const step=row.steps?.find(s=>s.id===p.step_id);if(step){step.checks=(step.checks||[]).filter(x=>x!==p.day);if(p.done)step.checks.push(p.day)}}}}result.objects=result.objects.filter(o=>!o.archived);return result}
 async function drain(){await ready;if(!pcUrl)return;if(draining){replayRequested=true;return}draining=true;try{const snapshot=await callPc('GET','/api/studio/snapshot');if(!snapshot?.installation_id)throw Error('Mets Windows TEST à jour pour synchroniser les albums et trackers.');const blocked=new Set();for(const job of pending()){if(job.base!==pcUrl)continue;const object=job.payload.id||job.payload.row_id||job.payload.step_id||job.payload.shopping_id||job.operation_id;if(job.identity!==snapshot.installation_id){job.conflict='Cette adresse correspond à une autre installation du PC.';await write([['job:'+job.operation_id,job]]);blocked.add(object);continue}if(job.conflict||blocked.has(object)){blocked.add(object);continue}try{const reply=await callPc('POST','/api/studio/actions',{operation_id:job.operation_id,action:job.action,payload:job.payload});const updated=structuredClone(records.get(key())||snapshot);if(job.action==='shopping-save'){updated.shopping||=[];const i=updated.shopping.findIndex(x=>x.id===reply.id);if(i>=0)updated.shopping[i]=reply.item;else updated.shopping.push(reply.item);updated.objects=updated.objects.filter(o=>o.id!==reply.appearance.id);updated.objects.push(reply.appearance)}if(job.action==='save'){const i=updated.objects.findIndex(o=>o.id===reply.id);if(i<0)updated.objects.push(reply);else updated.objects[i]=reply}await write([['job:'+job.operation_id,undefined],[key(),updated]])}catch(e){if(e.status>=400&&e.status<500){job.conflict=e.message||'Ce document a changé sur le PC.';await write([['job:'+job.operation_id,job]]);blocked.add(object);continue}throw e}}const current=await callPc('GET','/api/studio/snapshot');await write([[key(),{...current,base:pcUrl,saved_at:Date.now()}]]);last=Date.now();error='';if(window.AtelierWidget){try{window.AtelierWidget.sync(JSON.stringify({items:current.urgent||[],cycle:current.cycle||null,updated:Date.now()}))}catch{}}}catch(e){error=/UnknownHost|resolve host/i.test(e.message||'')?'Adresse du PC introuvable. Vérifie que Tailscale est connecté sur les deux appareils et que l’adresse est celle du PC.':e.message||'PC indisponible : tes changements restent conservés.'}finally{draining=false;window.dispatchEvent(new Event('studio-queue-updated'));if(replayRequested){replayRequested=false;queueMicrotask(()=>drain())}}}
 async function enqueue(action,payload,operation_id){await ready;const snapshot=records.get(key());if(!pcUrl||!snapshot?.installation_id)throw Error('Connecte une première fois le PC Windows TEST pour activer les albums et trackers partagés. Tes notes locales restent accessibles.');const changes=[],job={operation_id,action,payload,base:pcUrl,identity:snapshot.installation_id,order:++sequence};let result={ok:true};if(action==='asset'){const bytes=Uint8Array.from(atob(payload.base64),c=>c.charCodeAt(0)),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join(''),mime=bytes[0]===137?'image/png':bytes[0]===255&&bytes[1]===216?'image/jpeg':String.fromCharCode(...bytes.slice(8,12))==='WEBP'?'image/webp':String.fromCharCode(...bytes.slice(8,12))==='WAVE'?'audio/wav':bytes[0]===79?'audio/ogg':'audio/mpeg';changes.push(['asset:'+hash,{id:hash,mime,base64:payload.base64}]);result={id:hash,mime}}else if(action==='save')result={...payload,revision:payload.revision+1,_pending:true};changes.push(['job:'+operation_id,job]);await write(changes);goblinSnapshot('studio-edit');drain();return result}
 window.AtelierStudioTransport=async(path,options={})=>{await ready;if(path==='/api/studio/snapshot'){if(pcUrl&&(!records.get(key())||Date.now()-last>15000))await drain();return overlay(records.get(key()))}if(path==='/api/studio/actions'){const body=JSON.parse(options.body);return enqueue(body.action,body.payload,body.operation_id)}return callPc(options.method||'GET',path,options.body?JSON.parse(options.body):undefined)};
 window.StudioVault={ready,drain,peekDay:day=>overlay(records.get('day:'+pcUrl+':'+day)||records.get(key())),forDay:async day=>{await ready;const k='day:'+pcUrl+':'+day;try{const data=await callPc('GET','/api/studio/snapshot?day='+day);await write([[k,data]])}catch{}return overlay(records.get(k)||records.get(key()))},pending,status:()=>({error,draining,last}),snapshot:()=>overlay(records.get(key())),bindingChanged:()=>{try{window.AtelierWidget?.clear()}catch{}drain()},asset:async id=>{await ready;let a=records.get('asset:'+id);if(!a){a=await callPc('GET','/api/studio/assets/'+id+'?json=1');await write([['asset:'+id,a]])}return 'data:'+a.mime+';base64,'+a.base64},discard:async job=>{if(!confirm('Garder la version du PC et abandonner cette action locale ainsi que les modifications suivantes du même document ? Exporte une sauvegarde si tu veux conserver les deux.'))return;const same=pending().filter(j=>j.base===job.base&&j.action==='save'&&j.payload.id===job.payload.id||j.operation_id===job.operation_id);await write(same.map(j=>['job:'+j.operation_id,undefined]));await drain()},export:()=>window.goblinStudioBackup};
 ready.then(()=>{goblinSnapshot('studio-startup');drain()}).catch(e=>{error=e.message});setInterval(()=>{if(!document.hidden)drain()},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)drain()});
})();
